CREATE TABLE t
( database VARCHAR(100)
, table_name VARCHAR(100)
, space_utilised_kb VARCHAR(100)
, create_date VARCHAR(100)
, last_access_date VARCHAR(100)
, access_count VARCHAR(100)
, stats_rowcount VARCHAR(100));


update t set create_date = substr(create_date,7,4)||substr(create_date,4,2)||substr(create_date,1,2);
update t set last_access_date = substr(last_access_date,7,4)||substr(last_access_date,4,2)||substr(last_access_date,1,2);
